:root {
  --primary: #3b2f2f;
  --neutral: #faf6f1;
  --accent: #c97a3a;
  --space-4: 4px;
  --space-8: 8px;
  --space-16: 16px;
  --space-24: 24px;
  --space-32: 32px;
  --space-48: 48px;
  --space-64: 64px;
  --font-size-14: 14px;
  --font-size-16: 16px;
  --font-size-20: 20px;
  --font-size-24: 24px;
  --font-size-32: 32px;
  --font-size-48: 48px;
}

body {
  margin: 0;
  font-family: var(--font-size-16), sans-serif;
  background-color: var(--neutral);
  color: var(--primary);
}

.hero {
  display: grid;
  gap: var(--space-32);
  padding: var(--space-64);
  text-align: center;
  background-color: var(--primary);
  color: var(--neutral);
}

.hero h1 {
  font-size: var(--font-size-48);
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.hero p {
  font-size: var(--font-size-24);
  line-height: 1.6;
}

.features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-16);
  padding: var(--space-32);
}

.feature {
  background-color: var(--neutral);
  padding: var(--space-24);
  border-radius: var(--space-16);
}

.feature h2 {
  font-size: var(--font-size-32);
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.feature p {
  font-size: var(--font-size-16);
  line-height: 1.6;
}

.footer {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: var(--space-32);
  background-color: var(--primary);
  color: var(--neutral);
}

.footer p {
  font-size: var(--font-size-16);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .hero {
    grid-template-columns: 1fr;
    padding: var(--space-24);
  }

  .features {
    grid-template-columns: 1fr;
  }

  .footer {
    padding: var(--space-16);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

